VFT-C1.code:
@layer components {
  .status-badge {
    display: inline-flex;
    align-items: center;
    padding: var(--shelf-statusbadge-space-y) var(--shelf-statusbadge-space-x);
    border-radius: var(--shelf-statusbadge-radius);
    font-size: var(--shelf-statusbadge-text-size);
    font-weight: var(--shelf-statusbadge-text-weight);
    background-color: var(--shelf-statusbadge-bgColor-default);
    color: var(--shelf-statusbadge-fgColor-default);
    white-space: nowrap;
  }

  .status-badge[data-status="reading"] {
    background-color: var(--shelf-statusbadge-bgColor-reading);
    color: var(--shelf-statusbadge-fgColor-reading);
  }

  .status-badge[data-status="read"] {
    background-color: var(--shelf-statusbadge-bgColor-read);
    color: var(--shelf-statusbadge-fgColor-read);
  }

  .status-badge[data-status="want-to-read"] {
    background-color: var(--shelf-statusbadge-bgColor-want-to-read);
    color: var(--shelf-statusbadge-fgColor-want-to-read);
  }
}
